class Solution {
  public int numberOfWays(int numPeople) {
    final long MOD = 1_000_000_007L;
    int pairs = numPeople / 2;
    long[] dp = new long[pairs + 1]; // Catalan numbers: person 1 pairs with someone, splitting the circle
    dp[0] = 1;
    for (int p = 1; p <= pairs; p++)
      for (int left = 0; left < p; left++) dp[p] = (dp[p] + dp[left] * dp[p - 1 - left]) % MOD;
    return (int) dp[pairs];
  }
}
